class Solution {
public:
    int maxProductPath(vector<vector<int>>& grid) {
        const long long MOD = 1000000007;
        int m = grid.size(), n = grid[0].size();
        vector<long long> prev_max(n), prev_min(n), cur_max(n), cur_min(n);
        prev_max[0] = prev_min[0] = grid[0][0];
        for (int j = 1; j < n; j++) {
            prev_max[j] = prev_min[j] = prev_max[j - 1] * grid[0][j];
        }
        for (int i = 1; i < m; i++) {
            cur_max[0] = cur_min[0] = prev_max[0] * grid[i][0];
            for (int j = 1; j < n; j++) {
                long long v = grid[i][j];
                long long a = prev_max[j] * v;
                long long b = prev_min[j] * v;
                long long c = cur_max[j - 1] * v;
                long long d = cur_min[j - 1] * v;
                cur_max[j] = max({a, b, c, d});
                cur_min[j] = min({a, b, c, d});
            }
            swap(prev_max, cur_max);
            swap(prev_min, cur_min);
        }
        long long ans = prev_max[n - 1];
        if (ans < 0) return -1;
        return (int)(ans % MOD);
    }
};
